//! Shared consensus vectors. `tests/vectors/consensus_v1.json` is generated by the node
//! implementation (`network-common`'s `tests/consensus_vectors.rs`) and copied here by the sync.
//! This crate is a clean-room re-implementation, so it must reproduce every byte of every case.
//! Never edit the file by hand: a mismatch means this crate drifted from the node.

use filament_types::beacon_wire_header::WireBeaconHeader;
use filament_types::expand_voting::{
    admissible_s_bits_range, checked_s_bits_for_chain_count, compute_step_with, count_after_steps,
    s_bits_for_chain_count, shard_admissible_count_range, shard_reference_s_bits,
};
use filament_types::genesis::{BeaconGenesisConfig, ShardGenesisConfig};
use filament_types::genesis_network::{GenesisGenerator, NetworkGenesisConfig};
use filament_types::hash::{hash_pair, sha256d};
use filament_types::merged_mining_check::{verify_shard_id_and_mmn_with_ref_s, MergedMiningError};
use filament_types::shard_header::{BeaconHeader, FullShardHeader};
use filament_types::shard_body::{ShardBlockBody, TransactionDescriptor, TxInclusionProof};
use filament_types::transaction_impl::{ExtensionHeader, ExtensionRecord, FlatInput, FlatOutput, WitnessEntry};
use filament_types::pow_check::{validate_one_wire_beacon_chunk, validate_wire_beacon_headers_pow_seq};
use filament_types::merged_mining_hash::MergedMiningHash;
use filament_types::pow_target::{hash_meets_target, rbits_to_target};
use filament_types::hash_sorting::{extract_sorting_bits, find_eligible_shard};
use filament_types::mmr_math::{
    fork_path_positions, genesis_mmr_root, peak_descriptors, replay_peaks_after_appends,
};
use filament_types::relay_hash::relay_id;
use filament_types::tx_sighash::{prevouts_hash, sighash_v2};
use filament_types::txid::txid_from_parts;
use filament_types::weighted_hash::{
    bag_peaks_weighted_u128, hash_pair_weighted, rbits_add, rbits_to_u128_approx, u128_to_rbits,
    WeightedHash,
};
use filament_types::weighted_mmr_peaks::WeightedMMR;
use serde_json::Value;

const VECTORS: &str = include_str!("vectors/consensus_v1.json");

/// The slice of a beacon genesis the light client needs (everything else may differ freely).
fn genesis_summary(g: &BeaconGenesisConfig) -> Value {
    let e = &g.shard_expansion;
    serde_json::json!({
        "bits": g.bits, "bitcoin_anchor_hash": hex::encode(g.bitcoin_anchor_hash), "max_target": hex::encode(g.max_target),
        "asserted_s_bits": g.asserted_s_bits, "minimum_difficulty": g.minimum_difficulty.to_string(),
        "tree_depth": g.tree_depth, "shard_calibration": g.shard_calibration,
        "network_id": format!("{:?}", g.network_id), "version": g.version, "timestamp": g.timestamp,
        "difficulty": g.difficulty.to_string(), "bitcoin_anchor_height": g.bitcoin_anchor_height,
        "bitcoin_anchor_timestamp": g.bitcoin_anchor_timestamp, "genesis_message": g.genesis_message,
        "premine": g.premine.iter().map(|p| serde_json::json!([p.address, p.amount])).collect::<Vec<_>>(),
        "nonce": g.nonce, "expected_hash": g.expected_hash.map(|x| hex::encode(x)),
        "genesis_hash": GenesisGenerator::beacon_genesis_hash(g).ok().map(|x| hex::encode(x)),
        "expansion": {
            "initial_shard_count": e.initial_shard_count, "initial_s_bits": e.initial_s_bits,
            "threshold_numerator": e.threshold_numerator, "threshold_denominator": e.threshold_denominator,
            "step_numerator": e.step_numerator, "step_denominator": e.step_denominator,
            "activation_delay": e.activation_delay, "epoch_length": e.epoch_length,
        },
    })
}

fn body_from_json(v: &Value) -> ShardBlockBody {
    ShardBlockBody {
        outputs: v["outputs"].as_array().unwrap().iter()
            .map(|o| FlatOutput { value: o[0].as_u64().unwrap(), recipient: from_h32(&o[1]) }).collect(),
        inputs: v["inputs"].as_array().unwrap().iter()
            .map(|i| FlatInput { prev_height: i[0].as_u64().unwrap() as u32, prev_output_idx: i[1].as_u64().unwrap() as u16 }).collect(),
        witnesses: v["witnesses"].as_array().unwrap().iter().map(|w| WitnessEntry { witness_data: hv(w) }).collect(),
        extensions: v["extensions"].as_array().unwrap().iter().map(|e| {
            let payload = hv(&e[2]);
            ExtensionRecord {
                header: ExtensionHeader { extension_type: e[0].as_u64().unwrap() as u16, version: e[1].as_u64().unwrap() as u16, payload_length: payload.len() as u32 },
                payload,
            }
        }).collect(),
        descriptors: v["descriptors"].as_array().unwrap().iter().map(|d| {
            let n = |k: usize| d[k].as_u64().unwrap() as u32;
            TransactionDescriptor { out_start: n(0), out_len: n(1), in_start: n(2), in_len: n(3), witness_start: n(4), witness_len: n(5) as u16, extension_start: n(6), extension_len: n(7) as u16 }
        }).collect(),
    }
}

/// Everything the light client derives from a body: leaves, root, and a proof per output.
fn body_expectations(b: &ShardBlockBody) -> Value {
    let leaves: Vec<String> = (0..b.descriptors.len()).map(|i| h(&b.tx_leaf_hash(i).unwrap())).collect();
    let root = b.calculate_tx_merkle_root();
    let proofs: Vec<Value> = (0..b.outputs.len() as u32)
        .map(|o| {
            let p: TxInclusionProof = b.tx_inclusion_proof(7, o).expect("proof");
            assert!(p.verify(&root));
            serde_json::json!({"output_idx": o, "tx_idx": p.tx_idx, "path": p.path.iter().map(|x| h(x)).collect::<Vec<_>>(), "value_is_committed": p.value_is_committed()})
        })
        .collect();
    serde_json::json!({"leaves": leaves, "root": h(&root), "proofs": proofs})
}

fn aux_from_json(c: &Value) -> BeaconHeader {
    BeaconHeader {
        version: c["version"].as_u64().unwrap() as u32,
        delta: c["delta"].as_i64().unwrap() as i32,
        nonce: c["nonce"].as_u64().unwrap(),
        prev_mmr_root: wh(from_h32(&c["prev_mmr_root"])),
        merged_mining_root: from_h32(&c["merged_mining_root"]),
        bits: c["bits"].as_u64().unwrap() as u32,
        beacon_height: c["beacon_height"].as_u64().unwrap() as u32,
        beacon_merkle_root: from_h32(&c["beacon_merkle_root"]),
        coinbase_hash: from_h32(&c["coinbase_hash"]),
    }
}

struct MmCase { header: FullShardHeader, tree_depth: usize, expected: Option<(u16, u16)>, ref_s: Option<u32>, initial: [u8; 32], genesis_s: u32 }

fn mm_class(r: Result<(), MergedMiningError>) -> &'static str {
    match r {
        Ok(()) => "ok",
        Err(MergedMiningError::InvalidRbits(_)) => "invalid_rbits",
        Err(MergedMiningError::ChainCountAboveMaximum(_)) => "count_above_max",
        Err(MergedMiningError::InsufficientProofOfWork) => "insufficient_pow",
        Err(MergedMiningError::HashSorting(_)) => "hash_sorting",
        Err(MergedMiningError::ProofInvalid(_)) => "proof_invalid",
    }
}

fn mm_case_from_json(c: &Value) -> MmCase {
    let proof: Vec<MergedMiningHash> = c["proof"].as_array().unwrap().iter().map(|x| MergedMiningHash::from(from_h32(x))).collect();
    let header = FullShardHeader::new(
        c["height"].as_u64().unwrap() as u32, wh(from_h32(&c["prev_mmr_root"])), wh([0u8; 32]),
        from_h32(&c["tx_merkle_root"]), c["difficulty"].as_u64().unwrap() as u32, proof,
        c["shard_id"].as_u64().unwrap() as u16, aux_from_json(&c["aux"]),
    );
    MmCase {
        header,
        tree_depth: c["tree_depth"].as_u64().unwrap() as usize,
        expected: c["expected"].as_array().map(|a| (a[0].as_u64().unwrap() as u16, a[1].as_u64().unwrap() as u16)),
        ref_s: c["ref_s"].as_u64().map(|x| x as u32),
        initial: from_h32(&c["initial"]),
        genesis_s: c["genesis_s"].as_u64().unwrap() as u32,
    }
}

fn h(b: &[u8]) -> String {
    hex::encode(b)
}
fn hv(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().expect("hex string")).expect("hex")
}
fn from_h32(v: &Value) -> [u8; 32] {
    hv(v).try_into().expect("32 bytes")
}
fn wh(raw: [u8; 32]) -> WeightedHash {
    WeightedHash::from(raw)
}
fn dec(v: &Value) -> u128 {
    v.as_str().expect("decimal string").parse().expect("u128")
}
fn peaks_of(v: &Value) -> Vec<WeightedHash> {
    v.as_array().unwrap().iter().map(|p| wh(from_h32(p))).collect()
}

#[test]
fn every_shared_vector_matches() {
    let v: Value = serde_json::from_str(VECTORS).expect("vectors parse");
    assert_eq!(v["format"], 1);

    for c in v["sha256d"].as_array().unwrap() {
        assert_eq!(h(&sha256d(&hv(&c["data"]))), c["out"].as_str().unwrap());
    }
    for c in v["hash_pair"].as_array().unwrap() {
        assert_eq!(h(&hash_pair(&from_h32(&c["left"]), &from_h32(&c["right"]))), c["out"].as_str().unwrap());
    }
    let w = &v["weighted_hash"];
    for c in w["from_leaf_rbits"].as_array().unwrap() {
        let out = WeightedHash::from_leaf_rbits(&from_h32(&c["hash"]), c["rbits"].as_u64().unwrap() as u32);
        assert_eq!(h(out.raw()), c["out"].as_str().unwrap());
    }
    for c in w["from_anchor"].as_array().unwrap() {
        assert_eq!(h(WeightedHash::from_anchor(&from_h32(&c["hash"])).raw()), c["out"].as_str().unwrap());
    }
    for c in w["hash_pair_weighted"].as_array().unwrap() {
        let out = hash_pair_weighted(&wh(from_h32(&c["left"])), &wh(from_h32(&c["right"])));
        assert_eq!(h(out.raw()), c["out"].as_str().unwrap());
    }
    for c in w["rbits_add"].as_array().unwrap() {
        assert_eq!(rbits_add(c["a"].as_u64().unwrap() as u32, c["b"].as_u64().unwrap() as u32) as u64, c["out"].as_u64().unwrap());
    }
    for c in w["u128_to_rbits"].as_array().unwrap() {
        assert_eq!(u128_to_rbits(dec(&c["difficulty"])) as u64, c["out"].as_u64().unwrap());
    }
    for c in w["rbits_to_u128_approx"].as_array().unwrap() {
        assert_eq!(rbits_to_u128_approx(c["rbits"].as_u64().unwrap() as u32), dec(&c["out"]));
    }
    for c in w["bag_peaks_u128"].as_array().unwrap() {
        let (root, weight) = bag_peaks_weighted_u128(&peaks_of(&c["peaks"]), wh(from_h32(&c["anchor"])));
        assert_eq!(h(root.raw()), c["root"].as_str().unwrap());
        assert_eq!(weight, dec(&c["weight"]));
    }
    for c in w["peaks_after_append"].as_array().unwrap() {
        let (np, root, weight) = WeightedMMR::compute_peaks_after_append(
            &peaks_of(&c["peaks"]),
            c["leaf_count_before"].as_u64().unwrap() as u32,
            wh(from_h32(&c["leaf"])),
            wh(from_h32(&c["anchor"])),
        );
        let want: Vec<String> = c["new_peaks"].as_array().unwrap().iter().map(|p| p.as_str().unwrap().to_string()).collect();
        assert_eq!(np.iter().map(|p| h(p.raw())).collect::<Vec<_>>(), want);
        assert_eq!(h(root.raw()), c["root"].as_str().unwrap());
        assert_eq!(weight, dec(&c["weight"]));
    }
    for c in v["hash_sorting"].as_array().unwrap() {
        let x = hv(&c["hash"]);
        let k = c["k"].as_u64().unwrap() as u32;
        assert_eq!(extract_sorting_bits(&x, k) as u64, c["bits"].as_u64().unwrap());
        assert_eq!(find_eligible_shard(&x, k).map(|s| s as u64), c["shard"].as_u64());
    }
    for c in v["sighash"]["prevouts_hash"].as_array().unwrap() {
        let list: Vec<(u64, [u8; 32])> = c["prevouts"].as_array().unwrap().iter()
            .map(|p| (p[0].as_u64().unwrap(), from_h32(&p[1]))).collect();
        assert_eq!(h(&prevouts_hash(&list)), c["out"].as_str().unwrap());
    }
    for c in v["sighash"]["sighash_v2"].as_array().unwrap() {
        let out = sighash_v2(&from_h32(&c["txid"]), &from_h32(&c["prevouts_hash"]), c["input_index"].as_u64().unwrap() as u32);
        assert_eq!(h(&out), c["out"].as_str().unwrap());
    }
    for c in v["txid"].as_array().unwrap() {
        let inputs: Vec<(u32, u16)> = c["inputs"].as_array().unwrap().iter()
            .map(|p| (p[0].as_u64().unwrap() as u32, p[1].as_u64().unwrap() as u16)).collect();
        let outputs: Vec<(u64, [u8; 32])> = c["outputs"].as_array().unwrap().iter()
            .map(|p| (p[0].as_u64().unwrap(), from_h32(&p[1]))).collect();
        let payloads: Vec<Vec<u8>> = c["extensions"].as_array().unwrap().iter().map(|e| hv(&e[2])).collect();
        let exts: Vec<(u16, u16, &[u8])> = c["extensions"].as_array().unwrap().iter().zip(&payloads)
            .map(|(e, p)| (e[0].as_u64().unwrap() as u16, e[1].as_u64().unwrap() as u16, p.as_slice())).collect();
        let out = txid_from_parts(
            c["chain_id"].as_u64().unwrap() as u16,
            c["version"].as_u64().unwrap() as u8,
            c["locktime"].as_u64().unwrap() as u32,
            c["expiration_height"].as_u64().unwrap() as u32,
            &inputs, &outputs, &exts,
        );
        assert_eq!(h(&out), c["out"].as_str().unwrap());
    }
    let mm = &v["merged_mining_hash"];
    for c in mm["leaves"].as_array().unwrap() {
        assert_eq!(h(MergedMiningHash::from_active_leaf(&from_h32(&c["shard_hash"])).raw()), c["out"].as_str().unwrap());
    }
    for c in mm["combines"].as_array().unwrap() {
        let levels = c["levels"].as_array().unwrap();
        let mut cur: Vec<MergedMiningHash> = levels[0].as_array().unwrap().iter().map(|x| MergedMiningHash::from(from_h32(x))).collect();
        for want in &levels[1..] {
            cur = cur.chunks(2).map(|p| MergedMiningHash::combine(&p[0], &p[1])).collect();
            let got: Vec<String> = cur.iter().map(|x| h(x.raw())).collect();
            let want: Vec<String> = want.as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            assert_eq!(got, want);
        }
    }
    for c in mm["parts"].as_array().unwrap() {
        let prefix: [u8; 30] = hv(&c["prefix"]).try_into().unwrap();
        let x = MergedMiningHash::from_parts(&prefix, c["tree_height"].as_u64().unwrap() as u8, c["chain_count"].as_u64().unwrap() as u16);
        assert_eq!(h(x.raw()), c["out"].as_str().unwrap());
        assert_eq!(MergedMiningHash::chain_count_of_root(x.raw()) as u64, c["root_chain_count"].as_u64().unwrap());
        assert_eq!(MergedMiningHash::tree_height_of_root(x.raw()) as u64, c["root_tree_height"].as_u64().unwrap());
        let swapped = MergedMiningHash::root_with_chain_count(*x.raw(), c["swapped_count"].as_u64().unwrap() as u16);
        assert_eq!(h(&swapped), c["swapped"].as_str().unwrap());
    }
    for c in v["pow_target"]["targets"].as_array().unwrap() {
        let got = rbits_to_target(c["rbits"].as_u64().unwrap() as u32, &from_h32(&c["initial"]), c["s"].as_u64().unwrap() as u32);
        assert_eq!(h(&got), c["out"].as_str().unwrap());
    }
    for c in v["pow_target"]["meets"].as_array().unwrap() {
        assert_eq!(hash_meets_target(&from_h32(&c["hash"]), &from_h32(&c["target"])), c["out"].as_bool().unwrap());
    }
    let ev = &v["expand_voting"];
    for c in ev["s_bits"].as_array().unwrap() {
        let count = c["count"].as_u64().unwrap() as u16;
        assert_eq!(checked_s_bits_for_chain_count(count).map(u64::from), c["checked"].as_u64());
        if count <= 4095 {
            assert_eq!(Some(s_bits_for_chain_count(count) as u64), c["s"].as_u64());
        }
    }
    for c in ev["steps"].as_array().unwrap() {
        let (count, num, den) = (c["count"].as_u64().unwrap() as u16, c["num"].as_u64().unwrap() as u16, c["den"].as_u64().unwrap() as u16);
        assert_eq!(compute_step_with(count, num, den) as u64, c["step"].as_u64().unwrap());
        let got: Vec<u64> = [0u32, 1, 2, 5].iter().map(|k| count_after_steps(count, *k, num, den) as u64).collect();
        let want: Vec<u64> = c["after"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap()).collect();
        assert_eq!(got, want);
    }
    for c in ev["ranges"].as_array().unwrap() {
        let table: Vec<u16> = c["table"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u16).collect();
        let range = shard_admissible_count_range(c["epoch"].as_u64().unwrap() as u32, |e| table.get(e as usize).copied(), c["num"].as_u64().unwrap() as u16, c["den"].as_u64().unwrap() as u16);
        let want = c["range"].as_array().map(|a| (a[0].as_u64().unwrap() as u16, a[1].as_u64().unwrap() as u16));
        assert_eq!(range, want);
        assert_eq!(range.map(shard_reference_s_bits).map(u64::from), c["s_ref"].as_u64());
        let sr = range.map(admissible_s_bits_range);
        let want_sr = c["s_range"].as_array().map(|a| (a[0].as_u64().unwrap() as u8, a[1].as_u64().unwrap() as u8));
        assert_eq!(sr, want_sr);
    }
    for c in v["wire_pow"]["chunks"].as_array().unwrap() {
        let res = validate_one_wire_beacon_chunk(&hv(&c["chunk"]), &from_h32(&c["initial"]), c["genesis_s"].as_u64().unwrap() as u32);
        assert_eq!(res.is_ok(), c["ok"].as_bool().unwrap());
        assert_eq!(res.err(), c["err"].as_str());
    }
    for c in v["wire_pow"]["sequences"].as_array().unwrap() {
        let res = validate_wire_beacon_headers_pow_seq(&hv(&c["chunks"]), &from_h32(&c["initial"]), c["genesis_s"].as_u64().unwrap() as u32);
        let want = c["err"].as_array().map(|a| (a[0].as_u64().unwrap() as usize, a[1].as_str().unwrap().to_string()));
        assert_eq!(res.err().map(|(i, e)| (i, e.to_string())), want);
    }
    for c in v["genesis"]["presets"].as_array().unwrap() {
        let g = match c["name"].as_str().unwrap() {
            "mainnet" => BeaconGenesisConfig::mainnet(),
            "testnet1" => BeaconGenesisConfig::testnet1(),
            "testnet2" => BeaconGenesisConfig::testnet2(),
            "testnet3" => BeaconGenesisConfig::testnet3(),
            "devnet" => BeaconGenesisConfig::devnet(),
            "testnet_stress" => BeaconGenesisConfig::testnet_stress(),
            other => panic!("unknown preset {other}"),
        };
        assert_eq!(genesis_summary(&g), c["genesis"], "preset {}", c["name"]);
    }
    for c in v["genesis"]["files"].as_array().unwrap() {
        let cfg: NetworkGenesisConfig = toml::from_str(c["text"].as_str().unwrap()).unwrap();
        assert_eq!(genesis_summary(&cfg.beacon), c["genesis"], "file {}", c["name"]);
    }
    for c in v["genesis"]["shard_bits"].as_array().unwrap() {
        let got = ShardGenesisConfig::bits_from_beacon_nbits(c["beacon_rbits"].as_u64().unwrap() as u32, c["calibration"].as_u64().unwrap() as u32);
        assert_eq!(got as u64, c["out"].as_u64().unwrap());
    }
    for c in v["shard_body"].as_array().unwrap() {
        let b = body_from_json(&c["body"]);
        assert_eq!(body_expectations(&b), c["expect"]);
    }
    for c in v["shard_header"]["aux"].as_array().unwrap() {
        let aux = aux_from_json(c);
        assert_eq!(h(&aux.serialize_for_mining()), c["for_mining"].as_str().unwrap());
        assert_eq!(h(&aux.hash()), c["hash"].as_str().unwrap());
        assert_eq!(h(aux.hash_weighted().raw()), c["weighted"].as_str().unwrap());
    }
    for c in v["shard_header"]["headers"].as_array().unwrap() {
        let aux = aux_from_json(&v["shard_header"]["aux"][c["aux_index"].as_u64().unwrap() as usize]);
        let proof: Vec<MergedMiningHash> = c["proof"].as_array().unwrap().iter().map(|x| MergedMiningHash::from(from_h32(x))).collect();
        let mut sh = FullShardHeader::new(
            c["height"].as_u64().unwrap() as u32, wh(from_h32(&c["prev_mmr_root"])), wh(from_h32(&c["current_mmr_root"])),
            from_h32(&c["tx_merkle_root"]), c["difficulty"].as_u64().unwrap() as u32, proof, c["shard_id"].as_u64().unwrap() as u16, aux,
        );
        if let Some(rec) = c["beacon_coinbase"].as_str() {
            sh = sh.with_beacon_coinbase(hex::decode(rec).unwrap());
        }
        assert_eq!(h(&sh.serialize_for_hash()), c["for_hash"].as_str().unwrap());
        assert_eq!(h(&sh.hash()), c["hash"].as_str().unwrap());
        assert_eq!(h(&sh.merged_mining_leaf_hash()), c["leaf_hash"].as_str().unwrap());
        assert_eq!(h(sh.hash_weighted().raw()), c["weighted"].as_str().unwrap());
    }
    for c in v["merged_mining_check"].as_array().unwrap() {
        let m = mm_case_from_json(c);
        let res = mm_class(verify_shard_id_and_mmn_with_ref_s(&m.header, m.tree_depth, m.expected, m.ref_s, &m.initial, m.genesis_s));
        assert_eq!(res, c["result"].as_str().unwrap());
    }
    let m = &v["mmr_math"];
    for c in m["peak_descriptors"].as_array().unwrap() {
        let got: Vec<Vec<u64>> = peak_descriptors(c["leaf_count"].as_u64().unwrap() as u32)
            .iter().map(|(p, hh)| vec![*p as u64, *hh as u64]).collect();
        let want: Vec<Vec<u64>> = c["peaks"].as_array().unwrap().iter()
            .map(|p| vec![p[0].as_u64().unwrap(), p[1].as_u64().unwrap()]).collect();
        assert_eq!(got, want);
    }
    for c in m["replay_peaks_after_appends"].as_array().unwrap() {
        let leaves: Vec<WeightedHash> = c["leaves"].as_array().unwrap().iter().map(|p| wh(from_h32(p))).collect();
        let got = replay_peaks_after_appends(&peaks_of(&c["base_peaks"]), c["base_leaf_count"].as_u64().unwrap() as u32, &leaves);
        let want: Vec<Vec<String>> = c["after"].as_array().unwrap().iter()
            .map(|ps| ps.as_array().unwrap().iter().map(|p| p.as_str().unwrap().to_string()).collect()).collect();
        let got: Vec<Vec<String>> = got.iter().map(|ps| ps.iter().map(|p| h(p.raw())).collect()).collect();
        assert_eq!(got, want);
    }
    for c in m["genesis_mmr_root"].as_array().unwrap() {
        assert_eq!(h(genesis_mmr_root(&from_h32(&c["anchor_hash"]), wh(from_h32(&c["leaf"]))).raw()), c["out"].as_str().unwrap());
    }
    for c in m["fork_path_positions"].as_array().unwrap() {
        let got: Vec<Vec<u64>> = fork_path_positions(c["from"].as_u64().unwrap() as u32, c["to"].as_u64().unwrap() as u32)
            .iter().map(|(i, l)| vec![*i as u64, *l as u64]).collect();
        let want: Vec<Vec<u64>> = c["positions"].as_array().unwrap().iter()
            .map(|p| vec![p[0].as_u64().unwrap(), p[1].as_u64().unwrap()]).collect();
        assert_eq!(got, want);
    }
    for c in v["relay_id"].as_array().unwrap() {
        assert_eq!(h(&relay_id(&hv(&c["payload"]))), c["out"].as_str().unwrap());
    }
    for c in v["wire_beacon_header"].as_array().unwrap() {
        let hd = WireBeaconHeader {
            version: c["version"].as_u64().unwrap() as u32,
            prev_mmr_root: wh(from_h32(&c["prev_mmr_root"])),
            delta: c["delta"].as_i64().unwrap() as i32,
            bits: c["bits"].as_u64().unwrap() as u32,
            nonce: c["nonce"].as_u64().unwrap() as u32,
            height: c["height"].as_u64().unwrap() as u32,
            tx_merkle_root: from_h32(&c["tx_merkle_root"]),
            merged_mining_root: from_h32(&c["merged_mining_root"]),
            coinbase_hash: from_h32(&c["coinbase_hash"]),
        };
        assert_eq!(hd.root_chain_count() as u64, c["chain_count"].as_u64().unwrap());
        assert_eq!(h(&hd.serialize()), c["serialized"].as_str().unwrap());
        assert_eq!(WireBeaconHeader::deserialize(&hv(&c["serialized"])).unwrap(), hd);
        assert_eq!(h(&hd.commitment_hash()), c["commitment"].as_str().unwrap());
        assert_eq!(h(&hd.pow_hash()), c["pow_hash"].as_str().unwrap());
    }
}
